import { validateSecretName } from "./hosting.js";
/**
 * Why `keys` cannot be deployment secret names, or undefined when they fit.
 * A bad prefix fails here, with the channel id and the name, instead of
 * as a schema rejection of the whole manifest or a refused secret write.
 */
export function credentialEnvNameError(channelId, env) {
    for (const key of Object.values(env.keys)) {
        const error = validateSecretName(key);
        if (error !== undefined) {
            const prefix = env.envPrefix === "" ? "(none)" : env.envPrefix;
            return `channels/${channelId}: envPrefix ${prefix} makes credential env name ${JSON.stringify(key)} invalid. ${error}`;
        }
    }
    return undefined;
}
/**
 * Stored secret names that are the same credential under a different prefix
 * than a channel reads. A missing name is not a mismatch. The result names
 * only secret names, never values.
 */
export function credentialEnvMismatch(channels, stored) {
    const storedSet = new Set(stored);
    const declaredKeys = new Set(channels.flatMap((channel) => Object.values(channel.keys)));
    const mismatchedStored = [];
    const expected = [];
    for (const channel of channels) {
        for (const key of Object.values(channel.keys)) {
            if (storedSet.has(key)) {
                continue;
            }
            const suffix = suffixAfterPrefix(channel.envPrefix, key);
            if (suffix === undefined) {
                continue;
            }
            for (const name of stored) {
                // A name that is some channel's key is already the right prefix.
                if (declaredKeys.has(name)) {
                    continue;
                }
                if (name === suffix || name.endsWith(`_${suffix}`)) {
                    mismatchedStored.push(name);
                    expected.push(key);
                }
            }
        }
    }
    return {
        stored: [...new Set(mismatchedStored)].sort(),
        expected: [...new Set(expected)].sort(),
    };
}
export function formatCredentialEnvMismatch(args) {
    const { stored, expected } = args.mismatch;
    return (`warning: secrets stored on ${args.slug} do not match the credential env names the channels read: ${stored.join(", ")}\n` +
        `  the channels read ${expected.join(", ")}\n` +
        `  set them with \`${args.command} secret set ${args.slug} ${expected.join(" ")}\`\n`);
}
function suffixAfterPrefix(envPrefix, key) {
    if (envPrefix === "") {
        return key;
    }
    const marked = `${envPrefix}_`;
    if (!key.startsWith(marked) || key.length === marked.length) {
        return undefined;
    }
    return key.slice(marked.length);
}
